    "options": [
      "具体方法有：＂(I)亚硝酸钠－硫代硫酸钠疗法：立即将亚硝酸异戊酷1-2支包在手帕或纱布内打碎，给病人吸人15-30秒，每隔3分钟重复应用1支（一般最多用6支），直至使用亚硝酸钠为止",
      "接着静脉缓慢注射3%亚硝酸钠10-15ml,约2-3mVmin,注射时应密切观察血压，防止血压下降，必要时可隔0.5-1小时重复l次",
      "中的CN\"被结合后，组织与血液间的CN含量平衡破坏，组织中高浓度的CN又回到血液中，继续被高铁血红蛋白结合，使组织中细胞色素氧化酶逐渐恢复活性",
      "其代谢过程的反应式为：Na,S,0+NaCN+0=NaSCN+Na,SO,因此，解毒剂应首选高铁血红蛋白形成剂和供硫剂，以亚硫酸盐娇i代硫酸钠为领化物中毒首选解毒药物组合，疗效可靠"
    ],
